"""Original scalable settings ornaments; no raster stretching or rendered text."""
from pathlib import Path
root=Path(__file__).resolve().parent.parent/'game/assets/ui/settings'
root.mkdir(parents=True,exist_ok=True)
defs='''<defs><linearGradient id="gold" x2=".2" y2="1"><stop stop-color="#fff1bf"/><stop offset=".28" stop-color="#e9b75f"/><stop offset=".5" stop-color="#8d571f"/><stop offset=".72" stop-color="#ffe4a2"/><stop offset="1" stop-color="#bc812e"/></linearGradient><radialGradient id="metal" cx=".35" cy=".3"><stop stop-color="#fffbd6"/><stop offset=".32" stop-color="#ffe1a0"/><stop offset=".64" stop-color="#dba046"/><stop offset=".82" stop-color="#ffe5a1"/><stop offset="1" stop-color="#9d6424"/></radialGradient><linearGradient id="navy" x2=".7" y2="1"><stop stop-color="#0c2639"/><stop offset=".5" stop-color="#061726"/><stop offset="1" stop-color="#091d2e"/></linearGradient><radialGradient id="teal" cx=".7" cy=".8" r=".8"><stop stop-color="#00dfeb"/><stop offset=".45" stop-color="#008b9e"/><stop offset="1" stop-color="#051926"/></radialGradient><pattern id="weave" width="8" height="8" patternUnits="userSpaceOnUse"><path d="m0 0 8 8m-4 0 8 8m0-8 8 8" stroke="#7ca8b5" opacity=".035" stroke-width=".5"/></pattern></defs>'''
def svg(name,w,h,body):
 (root/(name+'.svg')).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w*3}" height="{h*3}" viewBox="0 0 {w} {h}">'+defs+body+'</svg>',encoding='utf-8')
